-- ── A5 — 증권거래세 3행: 원문 대조 완료 표기 ──
UPDATE policy_constants
   SET note = 'DRF 원문 대조 완료(대통령령 제36001호, 2026-01-01 시행)'
             || CASE WHEN key = 'sec_tax_kospi_farm' THEN ' · 농특세율 근거 농어촌특별세법 §5①5호(1만분의 15)' ELSE '' END,
       verified_at = '2026-09-17', updated_at = now()
 WHERE key IN ('sec_tax_kospi_trade', 'sec_tax_kospi_farm', 'sec_tax_kosdaq_trade');

-- ── A2 — stress_dsr_local: 출처 날짜 불일치 정정(값·상태는 그대로) ──
UPDATE policy_constants
   SET note = '⚠️ 근거 날짜 불일치(2026-09-17 정정): source_date 2025-12-10 문서는 2026-06-30까지(상반기)만 정한다 — 적용기간 2026-07-01~12-31 의 1차 근거가 아니다. 하반기 연장은 기사(파이낸셜뉴스·전자신문·뉴스핌 2026-06-30)로만 확인, 금융위 원문 미확보. | 교차: https://www.fnnews.com/news/202606301437527182',
       updated_at = now()
 WHERE key = 'stress_dsr_local';

-- ── 말미 카운트 단언 — 불일치면 전체 롤백 ──
DO $$
DECLARE c_ye int; c_simvat int; c_nps int; c_elec int; c_customs int; c_dui int; c_sec int; c_sdl int;
BEGIN
  SELECT count(*) INTO c_ye FROM policy_constants WHERE key LIKE 'ye\_%';
  SELECT count(*) INTO c_simvat FROM policy_constants WHERE key LIKE 'simvat\_%';
  SELECT count(*) INTO c_nps FROM policy_constants WHERE key LIKE 'nps\_%';
  SELECT count(*) INTO c_elec FROM policy_constants WHERE key LIKE 'elec\_%';
  SELECT count(*) INTO c_customs FROM policy_constants WHERE key LIKE 'customs\_%';
  SELECT count(*) INTO c_dui FROM policy_constants WHERE key LIKE 'dui\_%';
  SELECT count(*) INTO c_sec FROM policy_constants WHERE key LIKE 'sec\_tax\_%' AND note LIKE 'DRF 원문 대조 완료(대통령령 제36001호%';
  SELECT count(*) INTO c_sdl FROM policy_constants WHERE key = 'stress_dsr_local' AND note LIKE '⚠️ 근거 날짜 불일치%';
  IF c_ye <> 42 OR c_simvat <> 10 OR c_nps <> 8 OR c_elec <> 2 OR c_customs <> 1 OR c_dui <> 3 OR c_sec <> 3 OR c_sdl <> 1 THEN
    RAISE EXCEPTION 'k9_misc 단언 실패: ye=% simvat=% nps=% elec=% customs=% dui=% sec=% sdl=%',
      c_ye, c_simvat, c_nps, c_elec, c_customs, c_dui, c_sec, c_sdl;
  END IF;
END $$;
